schemas:
const schema = z.object({
  quoteId: z.string(),
  type: z.enum(["BATTERY", "EMS", "SOLAR", "ELECTRICAL", "CAMERA", "HEATPUMP"]),
  customerData: z.record(z.string(), z.unknown()),
  productIds: z.array(z.string()).optional(),
});

const schema = z.object({
  prompt: z.string().min(1),
  customerId: z.string().min(1),
});
const adviceResultSchema = z.object({
  title: z.string(),
  consumption: z.record(z.string(), z.unknown()).optional(),
  summary: z.string().optional(),
  analysis: z.string().optional(),
  calculation: z.record(z.string(), z.unknown()).optional(),
  scenarios: z.array(z.record(z.string(), z.unknown())).optional(),
  recommendation: z.string().optional(),
  financial: z.record(z.string(), z.unknown()).optional(),
  ems: z.record(z.string(), z.unknown()).optional(),
  backup: z.record(z.string(), z.unknown()).optional(),
  currentDevs: z.array(z.string()).optional(),
});

const schema = z.object({
  prompt: z.string().min(1),
  customerName: z.string().optional().default("de klant"),
  intent: z.enum(["quoteImport", "legacySection"]).optional().default("legacySection"),
});

const schema = z.object({
  type: z.enum(["intro", "outro", "item_description"]),
  context: z.object({
    companyName: z.string(),
    customerName: z.string(),
    items: z.array(z.object({ description: z.string(), qty: z.number(), unitPrice: z.number() })).optional(),
    itemName: z.string().optional(),
  }),
});

const schema = z.object({
  action: z.enum(["archive", "restore", "delete"]),
  ids: z.array(z.string().min(1)).min(1).max(200),
});

const schema = z.object({
  calculations: z.array(z.object({ id: z.string().min(1), role: z.enum(['BASE', 'VARIANT', 'OPTION']).optional(), sortOrder: z.number().int().min(0).optional() })).min(1).max(200),
  quoteId: z.string().min(1).optional(),
  customerId: z.string().min(1).optional(),
  title: z.string().trim().min(1).optional(),
  recommendedCalculationId: z.string().min(1).optional(),
  copyItems: z.literal(false).optional(),
});

const schema = z.object({
  from: z.object({ type: z.enum(["quote", "calculation"]), id: z.string().min(1) }),
  make: z.enum(["project", "workorder"]),
});

const schema = z.object({
  name: z.string().min(1),
  email: z.string().email().optional().or(z.literal("")),
  phone: z.string().optional(),
  address: z.string().optional(),
  city: z.string().optional(),
  zipCode: z.string().optional(),
  notes: z.string().optional(),
});

const schema = z.object({
  name: z.string().min(1),
  email: z.string().email().optional().or(z.literal("")),
  phone: z.string().optional(),
  address: z.string().optional(),
  city: z.string().optional(),
  zipCode: z.string().optional(),
  notes: z.string().optional(),
});

const schema = z.object({
  customerId: z.string().optional(),
  projectId: z.string().nullable().optional(),
  source: invoiceSourceSchema.optional(),
  lines: z.array(invoiceLineSchema).optional(),
  reference: z.string().optional(),
  notes: z.string().optional(),
});

const schema = z.object({
  status: z.enum(["CONCEPT", "GEREED", "BETAALD", "VERVALLEN"]).optional(),
  reference: z.string().nullable().optional(),
  notes: z.string().nullable().optional(),
  dueDate: z.string().nullable().optional(),
  invoiceDate: z.string().optional(),
  lines: z.array(lineSchema).optional(),
});

const updateSchema = z.object({
  price: z.coerce.number().min(0).nullable().optional(),
  notes: z.string().nullable().optional(),
});

const schema = z.object({
  scope: z.enum(["business", "private"]).default("business"),
  title: z.string().optional(),
  body: z.string().min(1, "Notitie mag niet leeg zijn"),
  projectId: z.string().nullish(),
  customerId: z.string().nullish(),
  pinned: z.boolean().optional(),
});

const schema = z.object({
  title: z.string().nullable().optional(),
  body: z.string().min(1).optional(),
  pinned: z.boolean().optional(),
  projectId: z.string().nullable().optional(),
  customerId: z.string().nullable().optional(),
  visibility: z.enum(["INTERNAL", "SHARED"]).optional(),
});

const schema = z.object({
  customerId: z.string().min(1),
  projectId: z.string().nullish(),
  name: z.string().optional(),
  email: z.string().email().optional().or(z.literal("")),
  label: z.string().optional(),
  canComment: z.boolean().optional(),
  canUpload: z.boolean().optional(),
});

const itemSchema = z.object({
  productId: z.string(),
  qty: z.number().min(0.01),
  notes: z.string().optional(),
  sortOrder: z.number().default(0),
});
const schema = z.object({
  name: z.string().min(1),
  description: z.string().optional(),
  category: z.string().optional(),
  items: z.array(itemSchema).min(1),
});

const itemSchema = z.object({
  productId: z.string(),
  qty: z.number().min(0.01),
  notes: z.string().optional(),
  sortOrder: z.number().default(0),
});
const schema = z.object({
  name: z.string().min(1),
  description: z.string().optional(),
  category: z.string().optional(),
  items: z.array(itemSchema).min(1),
});

const schema = z.object({
  customerId: z.string().min(1, "Klant is verplicht"),
  title: z.string().min(1, "Titel is verplicht"),
  description: z.string().optional(),
  status: z.enum(["OPEN", "IN_PROGRESS", "DONE", "ARCHIVED"]).optional(),
  address: z.string().optional(),
  city: z.string().optional(),
  zipCode: z.string().optional(),
});

const schema = z.object({
  title: z.string().trim().min(1).optional(),
  description: z.string().nullable().optional(),
  status: z.enum(["OPEN", "IN_PROGRESS", "DONE", "ARCHIVED"]).optional(),
  customerId: z.string().min(1).optional(),
  address: z.string().nullable().optional(),
  city: z.string().nullable().optional(),
  zipCode: z.string().nullable().optional(),
}).strict();

const lineSchema = z.object({
  description: z.string().min(1),
  qty: z.coerce.number().min(0).default(1),
  unit: z.string().optional(),
  unitPrice: z.coerce.number().default(0),
  vatRate: z.coerce.number().default(21),
});
const schema = z.object({
  reference: z.string().optional(),
  notes: z.string().optional(),
  fromQuoteId: z.string().optional(),
  fromWorkOrderId: z.string().optional(),
  lines: z.array(lineSchema).optional(),
});

const schema = z.object({
  name: z.string().min(1, "Naam is verplicht"),
  kind: z.enum(["LIVE", "IMAGE"]).default("LIVE"),
  url: z.string().url().optional().or(z.literal("")),
  imageKey: z.string().optional(),
  imageWidth: z.number().int().positive().optional(),
  imageHeight: z.number().int().positive().optional(),
});

const lineSchema = z.object({
  type: z.enum(["MATERIAAL", "ARBEID"]).default("MATERIAAL"),
  description: z.string().min(1),
  qty: z.coerce.number().min(0).default(1),
  unit: z.string().optional(),
  unitPrice: z.coerce.number().min(0).default(0),
  costPrice: z.coerce.number().nullable().optional(),
});
const schema = z.object({
  title: z.string().min(1, "Titel is verplicht"),
  description: z.string().optional(),
  scheduledAt: z.string().datetime().optional().or(z.literal("")),
  technicianName: z.string().optional(),
  fromQuoteId: z.string().optional(), // materiaal pre-invullen vanuit offerte
  lines: z.array(lineSchema).optional(),
});

const schema = z.object({
  supplierName: z.string().min(1).optional(),
  invoiceNumber: z.string().nullable().optional(),
  invoiceDate: z.string().datetime().nullable().optional().or(z.literal("")),
  amount: z.coerce.number().optional(),
  vatAmount: z.coerce.number().nullable().optional(),
  status: z.enum(["ONTVANGEN", "GEBOEKT", "BETAALD"]).optional(),
  notes: z.string().nullable().optional(),
});

const bodySchema = z.object({
  method: z.literal("verbal_confirmed"),
  signerName: z.string().trim().min(2).max(120),
  note: z.string().trim().max(2000).optional(),
});

const schema = z.object({
  title: z.string().trim().min(1).optional(),
  role: z.enum(["BASE", "VARIANT", "OPTION"]).optional(),
  /** Bestaande QuoteItem-regels overnemen in de nieuwe calculatie. */
  moveItems: z.boolean().optional(),
});

const bodySchema = z.object({
  // Aantal dagen dat de offerte er weer bij krijgt, of een expliciete datum.
  days: z.number().int().min(1).max(180).optional(),
  validUntil: z.string().datetime().optional(),
  note: z.string().trim().max(2000).optional(),
  emailSubject: z.string().trim().min(1).max(180).refine((value) => !/[\r\n]/.test(value)).optional(),
  emailMessage: z.string().trim().min(1).max(2000).optional(),
  // Standaard sturen we de klant een mail. Uit te zetten voor een stille verlenging.
  notifyCustomer: z.boolean().optional().default(true),
});

const restoreSchema = z.object({ versionId: z.string().min(1) }).strict();
const snapshotSchema = z.object({
  fields: z.object({ title: z.string().nullable(), category: z.string().nullable(), tagline: z.string().nullable(), intro: z.string().nullable(), outro: z.string().nullable(), itemsHeader: z.string().nullable(), hiddenSections: z.array(z.string()) }),
  commercial: z.unknown(),
  contentBlocks: z.array(z.object({ id: z.string(), type: z.string(), title: z.string().nullable(), body: z.string().nullable(), items: z.unknown(), tone: z.string().nullable(), imageUrl: z.string().nullable(), caption: z.string().nullable(), sortOrder: z.number().int() })),
});

const schema = z.object({
  fields: z.object({ title: z.string().trim().min(1).optional(), category: z.string().optional(), tagline: z.string().optional(),
    intro: z.string().optional(), outro: z.string().optional(), itemsHeader: z.string().optional(),
    hiddenSections: z.array(z.enum(["content", "approach", "visuals", "modules", "terms", "sources"])).optional(),
  }).strict().optional(),
  option: z.object({ id: z.string().min(1), changes: optionCopySchema.optional(), reset: z.boolean().optional() }).strict().optional(),
  item: z.object({ id: z.string().min(1), changes: itemCopySchema.optional(), reset: z.boolean().optional() }).strict().optional(),
  deleteBlockId: z.string().min(1).optional(),
  block: z.object({ id: z.string().min(1), changes: z.object({ title: z.string().optional(), body: z.string().optional(), items: z.array(z.unknown()).optional(), tone: z.enum(["info", "warning", "success"]).optional(), imageUrl: z.string().url().optional(), caption: z.string().optional() }).strict() }).strict().optional(),
  sectionOrder: presentationSchema.shape.sectionOrder,
  image: z.object({ url: z.string().url().refine((url) => url.startsWith("https://"), "Gebruik een HTTPS-afbeelding"), title: z.string().optional(), caption: z.string().optional() }).strict().optional(),
}).strict().refine((data) => Object.keys(data).length > 0, "Geef wijzigingen op");

const schema = z.object({
  action: z.enum(["archive", "restore", "delete"]),
  ids: z.array(z.string().min(1)).min(1).max(200),
});

const patchSchema = z.object({
  priceCents: z.number().int().min(0).optional(),
  nextBillingDate: z.string().optional(),
  status: z.enum(SUBSCRIPTION_STATUSES).optional(),
  serviceName: z.string().trim().min(1).max(200).optional(),
  notes: z.string().max(5000).nullish(),
  migrationPending: z.boolean().optional(),
});

const bodySchema = z
  .object({
    invoicedAt: z.string().datetime().optional(),
    periodsAdvanced: z.number().int().min(1).max(60).optional(),
  })
  .optional()
  .default({});

const schema = z.object({
  scope: z.enum(["business", "private"]).default("business"),
  name: z.string().min(1, "Naam is verplicht"),
  kind: z.enum(TASK_LIST_KINDS).default("LIST"),
  icon: z.string().optional(),
  color: z.string().optional(),
});

const schema = z.object({
  name: z.string().min(1).optional(),
  icon: z.string().nullable().optional(),
  color: z.string().nullable().optional(),
  sortOrder: z.number().int().optional(),
  archived: z.boolean().optional(),
});

const schema = z.object({
  body: z.string().min(1, "Bericht mag niet leeg zijn"),
  // INTERNAL op een gedeelde taak = mijn eigen kladblok, klant ziet 'm niet.
  visibility: z.enum(["INTERNAL", "SHARED"]).default("INTERNAL"),
});

const lineSchema = z.object({
  type: z.enum(["MATERIAAL", "ARBEID"]).default("MATERIAAL"),
  description: z.string().min(1),
  qty: z.coerce.number().min(0).default(1),
  unit: z.string().optional(),
  unitPrice: z.coerce.number().min(0).default(0),
  costPrice: z.coerce.number().nullable().optional(),
});
const schema = z.object({
  title: z.string().min(1).optional(),
  description: z.string().nullable().optional(),
  status: z.enum(["CONCEPT", "GEPLAND", "UITGEVOERD", "GEFACTUREERD"]).optional(),
  technicianName: z.string().nullable().optional(),
  scheduledAt: z.string().datetime().nullable().optional().or(z.literal("")),
  executedAt: z.string().datetime().nullable().optional().or(z.literal("")),
  lines: z.array(lineSchema).optional(),
});

const schema = z.object({
  // PNG als data-URL: "data:image/png;base64,...."
  dataUrl: z.string().regex(/^data:image\/png;base64,/, "Verwacht PNG data-URL"),
  signedBy: z.string().min(1, "Naam ondertekenaar verplicht"),
});
